result = diff_records(old, new, "id")

added = result["added"]
removed = result["removed"]
changed = result["changed"]

if not (added or removed or changed):
    print("snapshots match")
else:
    print(f"{len(added)} added, {len(removed)} removed, {len(changed)} changed")

# Whole records, in `after` / `before` order respectively.
for rec in added:
    print(f"+ {rec['id']}: {rec}")

for rec in removed:
    print(f"- {rec['id']}: {rec}")

# One entry per record on both sides with >=1 differing field, in `after` order.
# A half-populated delta means the field appeared ({"new": ...}) or vanished ({"old": ...}).
for entry in changed:
    print(f"~ {entry['key']}:")
    for field, delta in entry["changes"].items():
        if "old" in delta and "new" in delta:
            print(f"    {field}: {delta['old']!r} -> {delta['new']!r}")
        elif "new" in delta:
            print(f"    {field}: <absent> -> {delta['new']!r}")
        else:
            print(f"    {field}: {delta['old']!r} -> <absent>")

