"""List the top-level functions and classes defined in example.py, with line numbers."""

PATH = "example.py"

try:
    symbols = python_symbols(PATH)
except FileNotFoundError:
    print(f"{PATH}: no such file")
except IsADirectoryError:
    print(f"{PATH}: is a directory, expected a single .py file")
except UnicodeDecodeError:
    print(f"{PATH}: not UTF-8 source")
except SyntaxError as e:
    # The card guarantees filename/lineno/offset are populated, so report them
    # rather than guessing where the file went wrong.
    print(f"{e.filename}:{e.lineno}:{e.offset}: could not parse ({e.msg})")
else:
    if not symbols:
        # Documented: a file with no top-level definitions returns [], not an error.
        print(f"{PATH}: no top-level functions or classes")
    else:
        # Results come back in source order already, so no sorting needed.
        # `line` is the 1-based line of the def/class keyword (past any decorators).
        width = max(len(str(s["line"])) for s in symbols)
        for s in symbols:
            doc = "" if s["has_docstring"] else "  (no docstring)"
            print(f"{str(s['line']).rjust(width)}: {s['name']} [{s['kind']}]{doc}")
